// Changes: Tests of the grammar project operations used by the Definition tab.

import { describe, expect, it } from 'vitest'
import { analyzeGrammar } from './analysis'
import { fillDeclarationsFromRules, hasGrammar, loadTextbookExample } from './grammarOps'
import { defaultProjectData, type ProjectData } from './project'

const analyze = (d: ProjectData) => analyzeGrammar({ rules: d.ll.grammar, ...d.def })
const withDef = (patch: Partial<ProjectData['def']>, grammar = ''): ProjectData => {
  const d = defaultProjectData()
  return { ...d, ll: { ...d.ll, grammar }, def: { ...d.def, ...patch } }
}

describe('hasGrammar – would loading an example overwrite something?', () => {
  it('is false for an empty project', () => {
    expect(hasGrammar(defaultProjectData())).toBe(false)
    expect(hasGrammar(withDef({}, '  \n'))).toBe(false)
  })

  it('is true as soon as P, N, T or S is filled', () => {
    expect(hasGrammar(withDef({}, 'E -> i'))).toBe(true)
    expect(hasGrammar(withDef({ nonterminals: 'E' }))).toBe(true)
    expect(hasGrammar(withDef({ terminals: 'i' }))).toBe(true)
    expect(hasGrammar(withDef({ start: 'E' }))).toBe(true)
  })
})

describe('loadTextbookExample', () => {
  it('replaces N, T, P, S and the simulation input with a consistent LL(1) grammar', () => {
    const before = withDef({ nonterminals: 'X' }, 'X -> y')
    before.ll.input = 'y'
    const d = loadTextbookExample(before)
    const g = analyze(d)
    expect(g.S).toBe('E')
    expect(g.problems.definition[0].level).toBe('ok')
    expect(g.problems.ll[0].level).toBe('ok')
    expect(d.ll.input).toBe('i + i * i')
  })

  it('leaves the rest of the project alone', () => {
    const before = defaultProjectData()
    before.names.map = 'a=b'
    const d = loadTextbookExample(before)
    expect(d.names).toEqual(before.names)
    expect(d.prec).toEqual(before.prec)
  })
})

describe('fillDeclarationsFromRules', () => {
  it('declares every symbol of P that N and T are missing, keeping what is there', () => {
    const d = fillDeclarationsFromRules(withDef({ nonterminals: 'E  výraz\n', terminals: '' }, "E -> X '|' 'a b'\nX -> i"))
    expect(d.def.nonterminals).toBe('E  výraz\nX\n')
    const g = analyze(d)
    expect(g.missingN).toEqual([])
    expect(g.missingT).toEqual([])
    expect(g.T).toEqual(['|', 'a b', 'i'])
  })

  it('returns the same project when nothing is missing', () => {
    const d = withDef({ nonterminals: 'E', terminals: 'i' }, 'E -> i')
    expect(fillDeclarationsFromRules(d)).toBe(d)
  })
})
